import React, { useState } from "react";
import "./FemalePage.css"; // Your styling

const serviceDetails = {
  "Haircuts": "Customized haircuts to suit your personality.",
  "Coloring": "Hair coloring with the latest trends and safe products.",
  "Styling": "Styling services for events or casual looks.",
  "Hair Treatments": "Revitalizing treatments to restore hair health.",
};

const teamDetails = {
  "Emma Johnson": "Expert in modern cuts and vibrant coloring techniques.",
  "Olivia Smith": "Specialist in bridal styling and treatments.",
  "Ava Brown": "Known for creative and trendy hairstyles.",
  "Sophia Davis": "Experienced in hair care and customer service.",
};

const FemalePage = () => {
  const [expandedService, setExpandedService] = useState(null);
  const [expandedTeamMember, setExpandedTeamMember] = useState(null);
  const [name, setName] = useState("");
  const [feedback, setFeedback] = useState("");
  const [master, setMaster] = useState("");
  const [service, setService] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`Feedback submitted:\nName: ${name}\nFeedback: ${feedback}\nMaster: ${master}\nService: ${service}`);
    setName("");
    setFeedback("");
    setMaster("");
    setService("");
  };

  const toggleService = (serviceName) => {
    setExpandedService((prev) => (prev === serviceName ? null : serviceName));
    setExpandedTeamMember(null);
  };

  const toggleTeamMember = (name) => {
    setExpandedTeamMember((prev) => (prev === name ? null : name));
    setExpandedService(null);
  };

  return (
    <div className="female-page">
      <section className="hero-section">
        <div className="hero-text">
          <h1 className="text-4xl font-bold">Female Barbers</h1>
          <p className="mt-2 text-lg">Experience top-notch hair styling and care from our talented female barbers.</p>
        </div>
        <img src="/female-hero.jpg" alt="Female Barber Hero" className="hero-image" />
      </section>

      <section className="cards-section">
        <h2>Our Services</h2>
        <div className="cards-container">
          {Object.entries(serviceDetails).map(([service, description]) => (
            <div key={service} className="card" onClick={() => toggleService(service)}>
              <h3>{service}</h3>
              {expandedService === service && <p>{description}</p>}
            </div>
          ))}
        </div>
      </section>

      <section className="cards-section">
        <h2>Meet the Team</h2>
        <div className="cards-container">
          {Object.entries(teamDetails).map(([name, bio]) => (
            <div key={name} className="card" onClick={() => toggleTeamMember(name)}>
              <img
                src={`/${name.split(" ")[0].toLowerCase()}.jpg`}
                alt={name}
                onError={(e) => (e.target.src = "/default-female.jpg")}
                className="card-image"
              />
              <h3>{name}</h3>
              {expandedTeamMember === name && <p>{bio}</p>}
            </div>
          ))}
        </div>
      </section>

      <section className="feedback-form-container">
        <h2>Feedback Form</h2>
        <form onSubmit={handleSubmit} className="feedback-form">
          <input
            type="text"
            placeholder="Your Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />

          <textarea
            placeholder="Your Feedback"
            value={feedback}
            onChange={(e) => setFeedback(e.target.value)}
            required
          />

          <select value={master} onChange={(e) => setMaster(e.target.value)} required>
            <option value="">Select Master</option>
            {Object.keys(teamDetails).map((name) => (
              <option key={name} value={name}>{name}</option>
            ))}
          </select>

          <select value={service} onChange={(e) => setService(e.target.value)} required>
            <option value="">Select Service</option>
            {Object.keys(serviceDetails).map((service) => (
              <option key={service} value={service}>{service}</option>
            ))}
          </select>

          <button type="submit">Submit</button>
        </form>
      </section>
    </div>
  );
};

export default FemalePage;
